1,train,bon,1,400,12,0,200,rm_v3,40000,0,ok,train,1.56824,1.32579,451.787,0.49489
2,train,bon,1,400,64,0,200,rm_v3,40000,1,ok,train,3.17451,1.63172,553.277,0.3417
3,train,bon,1,400,256,0,200,rm_v3,40000,2,ok,train,4.54908,1.84794,612.765,0.30565
4,train,ppo,3.407,300,1,0,200,rm_v3,40000,3,ok,train,0.876082,1.07166,388.646,0.59969
5,train,ppo,3.407,900,1,0,200,rm_v3,40000,4,ok,train,2.01034,1.41898,483.703,0.45316
6,train,ppo,6.056,300,1,0,200,rm_v3,40000,5,ok,train,1.55725,1.30662,453.933,0.49565
----
